(() => {
  const sec = document.querySelector('section[data-module="loth-libro"]');
  if (!sec) return JSON.stringify({ err: 'sin banda', url: location.search });
  const R = (el) => { const b = el.getBoundingClientRect(); return [Math.round(b.top + scrollY), Math.round(b.height)]; };
  const vis = (el) => { const b = el.getBoundingClientRect(); const cs = getComputedStyle(el); return b.height > 0 && b.width > 0 && cs.visibility !== 'hidden'; };
  const lab = (c) => (c.getAttribute('aria-label') || c.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 28);
  const q = new URLSearchParams(location.search);
  const fila1 = sec.children[0];
  const hueco = sec.querySelector('[data-acciones-riel]');
  const enRiel = hueco ? [...hueco.querySelectorAll('button, a, input, select')].filter(vis).map(lab) : [];
  const finBanda = sec.getBoundingClientRect().bottom + scrollY;
  const raiz = sec.parentElement;
  const cont = [...raiz.children].filter((c) => c !== sec && vis(c));
  const datoSel = 'table tbody tr, [role=row]:not(:first-child), [role=grid], .leaflet-container, canvas, [data-primer-dato], [role=listitem], li[data-fila], svg[role=img]';
  const datos = [...raiz.querySelectorAll(datoSel)].filter((e) => vis(e) && !sec.contains(e) && !e.closest('[role=dialog]'));
  const dato = datos[0];
  const yDato = dato ? R(dato)[0] : null;
  const limite = yDato ?? (finBanda + 2000);
  const btns = [...raiz.querySelectorAll('button, a[href], input:not([type=hidden]), select')].filter((b) => vis(b) && !sec.contains(b) && !b.closest('[role=dialog]') && !b.closest('table'));
  const arriba = btns.filter((b) => R(b)[0] < limite).map((b) => lab(b) + '@' + R(b)[0]);
  const heads = [...raiz.querySelectorAll('h1,h2,h3,h4,[role=heading]')].filter((h) => vis(h) && !sec.contains(h)).slice(0, 6).map((h) => h.textContent.trim().slice(0, 36) + '@' + R(h)[0]);
  const tablists = [...raiz.querySelectorAll('[role=tablist],[role=radiogroup]')].filter((t) => vis(t) && !sec.contains(t)).map((t) => (t.getAttribute('aria-label') || '?') + ':' + [...t.querySelectorAll('[role=tab],[role=radio]')].map(lab).join('|') + '@' + R(t)[0]);
  const bloques = cont.flatMap((c) => (c.children.length === 1 ? [...c.children[0].children] : [...c.children])).filter(vis).slice(0, 10).map((c) => (c.tagName + '.' + String(c.className || '').split(' ').slice(0, 2).join('.')).slice(0, 34) + ' ' + R(c).join('/') + ' «' + (c.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 40) + '»');
  const txt = document.querySelector('main')?.innerText || '';
  return JSON.stringify({
    vista: q.get('vista'), sub: q.get('sub'),
    err: /excedido el límite|429|Demasiados pedidos/i.test(txt) ? '429' : null,
    banda: R(sec), fila1: R(fila1), riel: sec.children[1] ? R(sec.children[1]) : null, enRiel,
    yTabla: (() => { const t = [...raiz.querySelectorAll('table, [role=grid], [role=table]')].find((e) => vis(e) && !sec.contains(e) && !e.closest('[role=dialog]')); return t ? R(t)[0] : null; })(),
    yDato, dato: dato ? (dato.tagName + ' ' + (dato.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 40)) : null,
    arriba, nArriba: arriba.length, heads, tablists, bloques,
    altoDoc: document.documentElement.scrollHeight, pantallas: +(document.documentElement.scrollHeight / innerHeight).toFixed(2), vh: innerHeight,
    tablistScroll: (() => { const t = sec.querySelector('[role=tablist]:not([aria-label="Fase del libro"])'); return t ? [t.scrollWidth, t.clientWidth] : null; })(),
  });
})()

